import Foundation

/// Auto Zoom's Swift half (road map "creator-jobs" CU7, spec §11 CU-70…CU-76): the sheet's
/// settings and their remembered keys, the selected clips' cursor files found and read, and
/// `plan_zooms` asked of the core through `ReelCursor` (this file names no `rc_*`, CJ-8 (l))
/// with its answer read into ops. Both doors — Clip ▸ Auto Zoom… (`AutoZoomSheetController`)
/// and `auto_zoom` (`AgentServer+AutoZoom.swift`) — plan here.

/// What the sheet sets (CU-70's defaults). `typing` is never remembered: it is on whenever the
/// files hold typing (CU-76). `motionBlur` is the shutter the planned clips are given (spec §11
/// CU-118 (c)): the owner's 50 % by default, 0 for none.
struct AutoZoomSettings: Equatable {
    var zoom = 2.0, lead = 0.6, stay = 2.5
    var follow = true, typing = true, replace = false
    var motionBlur = 0.5

    static let zoomRange: ClosedRange<Double> = 1.25...4
    static let leadRange: ClosedRange<Double> = 0.2...2.0
    static let stayRange: ClosedRange<Double> = 0.5...10.0

    static let zoomKey = "FrameJobAutoZoomZoom"
    static let leadKey = "FrameJobAutoZoomLead"
    static let stayKey = "FrameJobAutoZoomStay"
    static let followKey = "FrameJobAutoZoomFollow"
    static let replaceKey = "FrameJobAutoZoomReplace"
    /// The sheet's "Motion blur" checkbox, remembered as a Bool: on is `motionBlurShutter`, off 0.
    static let motionBlurKey = "FrameJobAutoZoomMotionBlur"
    /// The shutter "Motion blur" sets when on (the owner's answer, 2026-11-01: a 180° shutter).
    static let motionBlurShutter = 0.5

    /// The remembered values, each clamped into its range; the default for a key not stored.
    /// Read through `double(forKey:)` and `bool(forKey:)`, so a launch argument's string
    /// (`-FrameJobAutoZoomLead 1`) reads as its number.
    static func remembered(_ d: UserDefaults) -> AutoZoomSettings {
        var s = AutoZoomSettings()
        func number(_ key: String, _ range: ClosedRange<Double>, _ value: inout Double) {
            guard d.object(forKey: key) != nil else { return }
            let v = d.double(forKey: key)
            if v.isFinite, v > 0 { value = min(max(v, range.lowerBound), range.upperBound) }
        }
        number(zoomKey, zoomRange, &s.zoom)
        number(leadKey, leadRange, &s.lead)
        number(stayKey, stayRange, &s.stay)
        if d.object(forKey: followKey) != nil { s.follow = d.bool(forKey: followKey) }
        if d.object(forKey: replaceKey) != nil { s.replace = d.bool(forKey: replaceKey) }
        if d.object(forKey: motionBlurKey) != nil {
            s.motionBlur = d.bool(forKey: motionBlurKey) ? motionBlurShutter : 0
        }
        return s
    }

    /// Writes only the keys whose value differs from `opened`'s, so a sheet whose controls
    /// were not changed writes nothing (mcp.py's DEFAULTS MOVED guard); `typing` never.
    func remember(changedFrom opened: AutoZoomSettings, in d: UserDefaults) {
        if zoom != opened.zoom { d.set(zoom, forKey: Self.zoomKey) }
        if lead != opened.lead { d.set(lead, forKey: Self.leadKey) }
        if stay != opened.stay { d.set(stay, forKey: Self.stayKey) }
        if follow != opened.follow { d.set(follow, forKey: Self.followKey) }
        if replace != opened.replace { d.set(replace, forKey: Self.replaceKey) }
        if motionBlur != opened.motionBlur { d.set(motionBlur > 0, forKey: Self.motionBlurKey) }
    }
}

/// `plan_zooms`' answer: the ops in the core's order and its counts, then the motion blur
/// `set_video` (CU-118 (c)) and `blurred`, how many clips it gives a shutter.
struct AutoZoomPlan {
    let ops: [ReelOp]
    let visits, added, replaced, dropped, closedAtCut, basesSet: Int
    let actions: [[String: Any]]
    let blurred: Int
}

enum AutoZoom {
    /// The undo step's name, both doors.
    static let actionName = "Auto Zoom"

    /// A sentence either door shows as it is.
    struct Refusal: LocalizedError {
        let message: String
        var errorDescription: String? { message }
    }

    /// The menu's test (CU-76): at least one clip, each a media clip whose media has a cursor
    /// file.
    static func canOffer(_ selection: [ClipSnapshot], in snapshot: ProjectSnapshot) -> Bool {
        !selection.isEmpty
            && selection.allSatisfy { clip in
                guard case .media(let id, _, _) = clip.source else { return false }
                return snapshot.media(id)?.cursor != nil
            }
    }

    /// Each clip's media's cursor file, by media id. Throws a clip that is not a media clip,
    /// a media with no cursor file, and a file that is missing, each in its sentence.
    static func cursorFiles(_ clips: [ClipSnapshot], in snapshot: ProjectSnapshot) throws
        -> [UInt32: URL]
    {
        var files: [UInt32: URL] = [:]
        for clip in clips {
            guard case .media(let id, _, _) = clip.source, let media = snapshot.media(id) else {
                throw Refusal(
                    message: "Clip \(clip.id) is not a media clip (it shows "
                        + "\(clip.source.kindName)), so it has no cursor file.")
            }
            guard media.cursor != nil, let file = cursorURL(for: media) else {
                throw Refusal(
                    message: "Media \(id) has no cursor file. A screen recording made by Frame "
                        + "Job has one; set_media_cursor attaches one.")
            }
            guard FileManager.default.fileExists(atPath: file.path) else {
                throw Refusal(
                    message: "Media \(id)'s cursor file \(file.lastPathComponent) is missing. "
                        + "The Media tab's Cursor section ▸ Locate…, or set_media_cursor, "
                        + "points it at the file.")
            }
            files[id] = file
        }
        return files
    }

    /// Opens each file through the core. Off the main thread: a file can be large.
    static func readTracks(_ files: [UInt32: URL]) throws -> [UInt32: ReelCursor] {
        var tracks: [UInt32: ReelCursor] = [:]
        for (media, file) in files {
            do {
                tracks[media] = try ReelCursor(data: try Data(contentsOf: file))
            } catch {
                let reason = (error as? ReelCoreError)?.message ?? error.localizedDescription
                throw Refusal(
                    message: "The cursor file \(file.lastPathComponent) could not be read: "
                        + reason)
            }
        }
        return tracks
    }

    /// Whether any file holds a typing stretch (CU-25's `typing` events).
    static func hasTyping(_ tracks: [UInt32: ReelCursor]) -> Bool {
        let request = #"{"events":{"from":0,"to":4611686018427387903,"kinds":["typing"]}}"#
        return tracks.values.contains { track in
            guard let text = try? track.query(request),
                let object = try? JSONSerialization.jsonObject(with: Data(text.utf8))
                    as? [String: Any]
            else { return false }
            return !((object["typing"] as? [Any]) ?? []).isEmpty
        }
    }

    /// `plan_zooms`' request JSON for `clips` (container ticks `from`/`to`, nil for none).
    static func request(
        _ clips: [UInt32], settings: AutoZoomSettings, from: Ticks?, to: Ticks?
    ) -> String {
        var args: [String: Any] = [
            "clips": clips.map { Int($0) }, "zoom": settings.zoom, "lead": settings.lead,
            "stay": settings.stay, "follow": settings.follow, "typing": settings.typing,
            "replace": settings.replace,
        ]
        if let from { args["from"] = from }
        if let to { args["to"] = to }
        let data = (try? JSONSerialization.data(withJSONObject: ["plan_zooms": args])) ?? Data()
        return String(decoding: data, as: UTF8.self)
    }

    /// Asks the core for the plan over `clips` of `project` (the edited one, so inside a nest
    /// the nest's), one track per clip; throws the core's sentence as a `Refusal`.
    static func plan(
        _ clips: [ClipSnapshot], tracks: [UInt32: ReelCursor], project: ReelProject,
        settings: AutoZoomSettings, from: Ticks?, to: Ticks?
    ) throws -> AutoZoomPlan {
        var ordered: [ReelCursor] = []
        for clip in clips {
            guard case .media(let id, _, _) = clip.source, let track = tracks[id] else {
                throw Refusal(message: "Clip \(clip.id)'s cursor file was not read.")
            }
            ordered.append(track)
        }
        let text: String
        do {
            text = try ReelCursor.query(
                request(clips.map(\.id), settings: settings, from: from, to: to),
                tracks: ordered, project: project)
        } catch {
            let reason = (error as? ReelCoreError)?.message ?? error.localizedDescription
            throw Refusal(message: sentence(reason))
        }
        guard let answer = try? JSONSerialization.jsonObject(with: Data(text.utf8))
            as? [String: Any]
        else { throw Refusal(message: "Auto Zoom's plan could not be read.") }
        var ops = try ((answer["ops"] as? [[String: Any]]) ?? []).map(op)
        func count(_ key: String) -> Int { (answer[key] as? NSNumber)?.intValue ?? 0 }
        let actions = (answer["actions"] as? [[String: Any]]) ?? []
        let blurred = unblurred(actions, in: project.snapshot)
        if settings.motionBlur > 0, !blurred.isEmpty {
            ops.append(
                .setVideo(clips: blurred, patch: VideoPatch(motionBlur: settings.motionBlur)))
        }
        return AutoZoomPlan(
            ops: ops, visits: count("visits"), added: count("added"),
            replaced: count("replaced"), dropped: count("dropped"),
            closedAtCut: count("closed_at_cut"), basesSet: count("bases_set"),
            actions: actions, blurred: settings.motionBlur > 0 ? blurred.count : 0)
    }

    /// The distinct clips the planned actions name, in first-named order, whose BASE
    /// `video.motion_blur` is 0 (CU-118 (c)): a clip that already has a shutter keeps it.
    private static func unblurred(_ actions: [[String: Any]], in snapshot: ProjectSnapshot)
        -> [UInt32]
    {
        var clips: [UInt32] = []
        for action in actions {
            guard let id = (action["clip"] as? NSNumber)?.uint32Value, !clips.contains(id),
                let clip = snapshot.clip(id), (clip.video?.motionBlur ?? 0) <= 0
            else { continue }
            clips.append(id)
        }
        return clips
    }

    /// The core's lowercase sentence as one a person reads: capitalised, with a full stop.
    static func sentence(_ core: String) -> String {
        guard let first = core.first else { return core }
        let text = first.uppercased() + core.dropFirst()
        return text.hasSuffix(".") ? text : text + "."
    }

    /// One op of the answer, through `ReelOps.swift`'s factories.
    private static func op(_ o: [String: Any]) throws -> ReelOp {
        func id(_ key: String) -> UInt32 { (o[key] as? NSNumber)?.uint32Value ?? 0 }
        func ticks(_ key: String) -> Ticks { (o[key] as? NSNumber)?.int64Value ?? 0 }
        switch o["op"] as? String {
        case "remove_action":
            return .removeAction(clip: id("clip"), action: id("action"))
        case "set_video":
            let clips = ((o["clips"] as? [NSNumber]) ?? []).map(\.uint32Value)
            return .setVideoRaw(clips: clips, patch: o["patch"] ?? [String: Any]())
        case "add_zoom_action":
            return .addZoomActionRaw(
                clip: id("clip"), at: ticks("at"), duration: ticks("duration"),
                region: o["region"] ?? NSNull(),
                fit: (o["fit"] as? String).flatMap(ZoomFit.init(rawValue:)),
                curve: (o["curve"] as? String).flatMap(Curve.init(rawValue:)))
        default:
            throw Refusal(message: "Auto Zoom's plan named an op it does not make.")
        }
    }
}
import AppKit

/// Clip ▸ Auto Zoom… (road map "creator-jobs" CU7, spec §11 CU-76): zooms planned from the
/// selected clips' cursor files — Zoom, Arrive before the click, Stay after the last activity,
/// Follow the cursor while zoomed, Zoom on typing, Replace existing zooms, and Motion blur
/// (CU11b, spec §11 CU-118 (d): the zoomed clips given the owner's 50 % shutter) — applied as
/// one undo step "Auto Zoom". `auto_zoom` (`AgentServer+AutoZoom.swift`) plans through the same
/// `AutoZoom.plan`.
///
/// The sheet opens with the remembered values (`AutoZoomSettings.remembered`), reads the files
/// off the main thread ("Reading cursor files…", Zoom disabled), then plans on main at every
/// control change and says what it would do, or the refusal. Zoom applies the plan, then writes
/// only the keys whose value changed. Zoom on typing is on, and enabled, only when a file has
/// typing stretches, and is never remembered.
///
/// **The dev accept** (`-RCDevAutoZoomAccept YES`, dev tools only): the sheet presses Zoom once
/// its first plan exists, with its controls as set (AU-128's precedent).
final class AutoZoomSheetController: NSViewController, NSTextFieldDelegate {
    /// The dev-only launch default that presses Zoom.
    static let devAcceptKey = "RCDevAutoZoomAccept"

    private weak var document: ProjectDocument?
    private let clipIDs: [UInt32]
    private let opened: AutoZoomSettings
    private var tracks: [UInt32: ReelCursor]?
    private var plan: AutoZoomPlan?
    private var accepted = false

    private let zoomField = NSTextField(string: "")
    private let leadField = NSTextField(string: "")
    private let stayField = NSTextField(string: "")
    private let followBox = NSButton(
        checkboxWithTitle: "Follow the cursor while zoomed", target: nil, action: nil)
    private let typingBox = NSButton(
        checkboxWithTitle: "Zoom on typing", target: nil, action: nil)
    private let replaceBox = NSButton(
        checkboxWithTitle: "Replace existing zooms", target: nil, action: nil)
    private let motionBlurBox = NSButton(
        checkboxWithTitle: "Motion blur", target: nil, action: nil)
    private let summaryLabel = NSTextField(wrappingLabelWithString: "")
    private var zoomButton: NSButton?

    init(document: ProjectDocument, clips: [UInt32]) {
        self.document = document
        self.clipIDs = clips
        self.opened = AutoZoomSettings.remembered(.standard)
        super.init(nibName: nil, bundle: nil)
    }

    @available(*, unavailable)
    required init?(coder: NSCoder) {
        fatalError("AutoZoomSheetController does not support NSCoder")
    }

    // MARK: - View

    override func loadView() {
        style(zoomField, range: AutoZoomSettings.zoomRange, value: opened.zoom)
        style(leadField, range: AutoZoomSettings.leadRange, value: opened.lead)
        style(stayField, range: AutoZoomSettings.stayRange, value: opened.stay)
        for (box, on) in [
            (followBox, opened.follow), (typingBox, false), (replaceBox, opened.replace),
            (motionBlurBox, opened.motionBlur > 0),
        ] {
            box.state = on ? .on : .off
            box.font = DS.sans(13)
            box.target = self
            box.action = #selector(controlChanged(_:))
        }
        typingBox.isEnabled = false
        summaryLabel.font = DS.sans(12)
        summaryLabel.textColor = DS.textMuted
        summaryLabel.preferredMaxLayoutWidth = sheetWidth - sheetInset * 2
        summaryLabel.stringValue = "Reading cursor files…"
        summaryLabel.setAccessibilityIdentifier("autozoom.summary")

        let grid = makeSheetGrid([
            [fieldLabel("Zoom:"), sheetRow([zoomField, fieldLabel("×")])],
            [fieldLabel("Arrive:"), sheetRow([leadField, fieldLabel("s before the click")])],
            [fieldLabel("Stay:"), sheetRow([stayField, fieldLabel("s after the last activity")])],
            [NSGridCell.emptyContentView, followBox],
            [NSGridCell.emptyContentView, typingBox],
            [NSGridCell.emptyContentView, replaceBox],
            [NSGridCell.emptyContentView, motionBlurBox],
        ])
        let cancel = sheetCancelButton(target: self, action: #selector(cancelClicked(_:)))
        let zoom = StickerButton(
            title: "Zoom", style: .primary, target: self, action: #selector(zoomClicked(_:)))
        zoom.isEnabled = false
        zoomButton = zoom
        view = makeSheetView(
            title: "Auto Zoom",
            hint: "Zooms in where the recording's clicks and typing are, and back out after. "
                + "Each zoom is an ordinary action. One undo step.",
            content: sheetColumn([grid, summaryLabel]),
            buttonRow: makeButtonRow(cancel: cancel, apply: zoom))
    }

    private func style(_ field: NSTextField, range: ClosedRange<Double>, value: Double) {
        let formatter = NumberFormatter()
        formatter.numberStyle = .decimal
        formatter.allowsFloats = true
        formatter.minimumFractionDigits = 0
        formatter.maximumFractionDigits = 2
        formatter.minimum = NSNumber(value: range.lowerBound)
        formatter.maximum = NSNumber(value: range.upperBound)
        field.formatter = formatter
        field.delegate = self
        field.alignment = .right
        field.doubleValue = value
        field.widthAnchor.constraint(equalToConstant: 64).isActive = true
        DSField.style(field)
    }

    override func viewDidAppear() {
        super.viewDidAppear()
        guard tracks == nil, let document else { return }
        let snapshot = document.editedProject.snapshot
        let clips = clipIDs.compactMap { snapshot.clip($0) }
        let files: [UInt32: URL]
        do {
            files = try AutoZoom.cursorFiles(clips, in: snapshot)
        } catch {
            summaryLabel.stringValue = error.localizedDescription
            return
        }
        DispatchQueue.global(qos: .userInitiated).async { [weak self] in
            let read = Result { try AutoZoom.readTracks(files) }
            DispatchQueue.main.async { self?.didRead(read) }
        }
    }

    private func didRead(_ read: Result<[UInt32: ReelCursor], Error>) {
        switch read {
        case .failure(let error):
            summaryLabel.stringValue = error.localizedDescription
        case .success(let tracks):
            self.tracks = tracks
            let typing = AutoZoom.hasTyping(tracks)
            typingBox.isEnabled = typing
            typingBox.state = typing ? .on : .off
            replan()
            #if FRAMEJOB_DEV_TOOLS
            if plan != nil, !accepted, UserDefaults.standard.bool(forKey: Self.devAcceptKey) {
                accepted = true
                DispatchQueue.main.async { [weak self] in self?.zoomClicked(nil) }
            }
            #endif
        }
    }

    // MARK: - Values

    /// What the controls say, each number inside its range.
    private var settings: AutoZoomSettings {
        func clamped(_ field: NSTextField, _ range: ClosedRange<Double>) -> Double {
            min(max(field.doubleValue, range.lowerBound), range.upperBound)
        }
        var s = AutoZoomSettings()
        s.zoom = clamped(zoomField, AutoZoomSettings.zoomRange)
        s.lead = clamped(leadField, AutoZoomSettings.leadRange)
        s.stay = clamped(stayField, AutoZoomSettings.stayRange)
        s.follow = followBox.state == .on
        s.typing = typingBox.isEnabled && typingBox.state == .on
        s.replace = replaceBox.state == .on
        s.motionBlur = motionBlurBox.state == .on ? AutoZoomSettings.motionBlurShutter : 0
        return s
    }

    /// Plans again on main and says what Zoom would do.
    private func replan() {
        guard let document, let tracks else { return }
        let snapshot = document.editedProject.snapshot
        let clips = clipIDs.compactMap { snapshot.clip($0) }
        do {
            let plan = try AutoZoom.plan(
                clips, tracks: tracks, project: document.editedProject, settings: settings,
                from: nil, to: nil)
            self.plan = plan
            summaryLabel.stringValue = Self.summary(plan)
            zoomButton?.isEnabled = true
        } catch {
            plan = nil
            summaryLabel.stringValue = error.localizedDescription
            zoomButton?.isEnabled = false
        }
    }

    /// "N zooms in V visits", and the drops.
    static func summary(_ plan: AutoZoomPlan) -> String {
        let zooms = plan.added == 1 ? "1 zoom" : "\(plan.added) zooms"
        let visits = plan.visits == 1 ? "1 visit" : "\(plan.visits) visits"
        var text = "\(zooms) in \(visits)."
        if plan.dropped > 0 {
            text += " \(plan.dropped) dropped where an action is already set."
        }
        return text
    }

    // MARK: - Controls

    @objc private func controlChanged(_ sender: Any?) {
        replan()
    }

    func controlTextDidEndEditing(_ obj: Notification) {
        guard let field = obj.object as? NSTextField else { return }
        let range =
            field === zoomField
            ? AutoZoomSettings.zoomRange
            : field === leadField ? AutoZoomSettings.leadRange : AutoZoomSettings.stayRange
        field.doubleValue = min(max(field.doubleValue, range.lowerBound), range.upperBound)
        replan()
    }

    // MARK: - Commit

    @objc private func cancelClicked(_ sender: Any?) {
        dismiss(self)
    }

    @objc private func zoomClicked(_ sender: Any?) {
        replan()
        guard let document, let plan else { return }
        let settings = self.settings
        dismiss(self)
        if !plan.ops.isEmpty {
            document.applyEdit(AutoZoom.actionName, plan.ops)
        }
        settings.remember(changedFrom: opened, in: .standard)
    }
}
import AppKit

/// Clip ▸ Auto Zoom… (road map "creator-jobs" CU7, spec §11 CU-76): the selected clips of the
/// container being edited — the timeline, or the open nest — put up in
/// `AutoZoomSheetController`, whose Zoom applies `plan_zooms`' ops as one undo step. `auto_zoom`
/// mirrors it (`AgentServer+AutoZoom.swift`).
extension EditorViewController {

    /// The selected clips the menu offers Auto Zoom on, in id order; empty when any of them
    /// is not a media clip whose media has a cursor file.
    private func autoZoomClips(_ document: ProjectDocument) -> [UInt32] {
        let snapshot = document.editedProject.snapshot
        let clips = document.selection.sorted().compactMap { snapshot.clip($0) }
        guard clips.count == document.selection.count,
            AutoZoom.canOffer(clips, in: snapshot)
        else { return [] }
        return clips.map(\.id)
    }

    @objc func showAutoZoomSheet(_ sender: Any?) {
        guard let document, view.window?.attachedSheet == nil else {
            NSSound.beep()
            return
        }
        let clips = autoZoomClips(document)
        guard !clips.isEmpty else {
            NSSound.beep()
            return
        }
        presentAsSheet(AutoZoomSheetController(document: document, clips: clips))
    }

    /// The menu arm, answered from `validateUserInterfaceItem`'s default case; nil for any
    /// other action. On with at least one selected clip, each a media clip whose media has a
    /// cursor file, and no sheet on the window; allowed inside a nest.
    func validateAutoZoomAction(_ action: Selector) -> Bool? {
        guard action == #selector(showAutoZoomSheet(_:)) else { return nil }
        guard let document, view.window?.attachedSheet == nil else { return false }
        return !autoZoomClips(document).isEmpty
    }
}

1	//! Auto Zoom's visits (spec §11 CU-70): anchors in container time become
2	//! visits, and visits become planned zoom-ins, pans, follow pans and zoom
3	//! backs, still in container time and not yet on any clip. Pure: no
4	//! `Project`, no cursor file — `cursor_zoom.rs` maps the file into
5	//! [`Anchor`]s, scroll-burst starts, barriers and a cursor sampler, and
6	//! moves what comes back onto clips (CU-74).
7	//!
8	//! Positions are in P: source pixels from the centre of the UNCROPPED
9	//! picture, y down. A region is centred on its aim and clamped inside the
10	//! cropped rect ([`Frame`]); `cursor_zoom.rs` turns P into Q per clip.
11	//!
12	//! **Barriers** are cuts a hold may not cross (a cut into a clip that was
13	//! not given, or into one whose kept action meets the hold) and the run's
14	//! end. No visit spans one; a visit whose zoom back would end past one is
15	//! closed with a zoom back ending at it, counted when the barrier is a cut.
16	
17	use crate::time::{Ticks, TIMESCALE};
18	
19	/// A zoom back's length: 0.8 s.
20	pub(crate) const BACK: Ticks = TIMESCALE * 8 / 10;
21	/// A follow pan's length: 0.5 s.
22	const FOLLOW_PAN: Ticks = TIMESCALE / 2;
23	/// How long the cursor stays outside the inner 70 % before a follow pan.
24	const FOLLOW_OUTSIDE: Ticks = TIMESCALE * 3 / 10;
25	/// At most one follow pan a second, start to start.
26	const FOLLOW_EVERY: Ticks = TIMESCALE;
27	/// The follow sampler's step: 10 Hz.
28	const SAMPLE: Ticks = TIMESCALE / 10;
29	/// A zoom back ending under this before the next zoom-in starts merges.
30	const MERGE_GAP: Ticks = TIMESCALE;
31	/// Half the inner part an anchor must leave to pan: 60 %.
32	const ANCHOR_HALF: f64 = 0.3;
33	/// Half the inner part the followed cursor must leave: 70 %.
34	const FOLLOW_HALF: f64 = 0.35;
35	
36	/// One anchor: a down click, or a typing stretch aimed per CU-72.
37	#[derive(Debug, Clone, Copy)]
38	pub(crate) struct Anchor {
39	    /// Container time of the click, or of the stretch's first mark.
40	    pub t: Ticks,
