485	/// Answers `plan_zooms` (CU-70…CU-75) against `tracks`, one per clip.
486	pub(crate) fn plan_zooms(
487	    tracks: &[&CursorTrack],
488	    project: &Project,
489	    args: PlanZoomsArgs,
490	) -> Result<Value, String> {
491	    in_range("zoom", "", args.zoom, 1.25, 4.0)?;
492	    in_range("lead", " s", args.lead, 0.2, 2.0)?;
493	    in_range("stay", " s", args.stay, 0.5, 10.0)?;
494	    if let (Some(from), Some(to)) = (args.from, args.to) {
495	        if to <= from {
496	            return Err(format!("to ({to}) must be after from ({from})"));
497	        }
498	    }
499	    if args.clips.is_empty() {
500	        return Err("plan_zooms needs at least one clip".into());
501	    }
502	    if tracks.len() != args.clips.len() {
503	        return Err(format!(
504	            "plan_zooms reads one cursor track per clip; {} clips and {} tracks were given",
505	            args.clips.len(),
506	            tracks.len()
507	        ));
508	    }
509	    let runs = check(project, &args.clips)?;
510	    let window = (
511	        args.from.unwrap_or(Ticks::MIN),
512	        args.to.unwrap_or(Ticks::MAX),
513	    );
514	    // CU-71: what Replace removes; `next` is the project as it will be at
515	    // apply — the removals, then the bases this plan sets.
516	    let mut next = project.clone();
517	    let mut removed: Vec<(u32, u32)> = Vec::new();
518	    if args.replace {
519	        for &id in &args.clips {
520	            let clip = project.require_clip(id)?;
521	            for a in clip.actions.iter().filter(|a| is_zoom(a)) {
522	                let s = clip.start.saturating_add(a.start);
523	                if s < window.1 && window.0 < s.saturating_add(a.duration) {
524	                    removed.push((id, a.id));
525	                }
526	            }
527	            if let Some(c) = next.clip_mut(id) {
528	                c.actions.retain(|a| !removed.contains(&(id, a.id)));
529	            }
530	        }
531	    }
532	    let timing = Timing {
533	        lead: seconds_to_ticks(args.lead),
534	        stay: seconds_to_ticks(args.stay),
535	        follow: args.follow,
536	        frame: project.frame(),
537	    };
538	    let mut bases: Vec<(u32, Placement)> = Vec::new();
539	    // Each landed span with its run's rest and zoomed scale.
540	    let mut landed: Vec<(u32, Planned, Placement, f64)> = Vec::new();
541	    let (mut visit_count, mut closed) = (0, 0);
542	    let mut heads: Vec<u32> = Vec::new();
543	    for run_clips in runs {
544	        let Some(&head) = run_clips.first() else {
545	            continue;
546	        };
547	        if heads.contains(&head.id) {
548	            continue;
549	        }
550	        heads.push(head.id);
551	        let rest = placement(head);
552	        let scale = rest.0 * args.zoom;
553	        let media = media_in(head).and_then(|(m, _)| project.media(m));
554	        let half = media.map_or((0.0, 0.0), |m| {
555	            (f64::from(m.width) / 2.0, f64::from(m.height) / 2.0)
556	        });
557	        let run = Run {
558	            clips: run_clips,
559	            given: &args.clips,
560	            tracks,
561	            next: &next,
562	            window,
563	            typing: args.typing,
564	            half,
565	        };
566	        let frame = run.frame(scale);
567	        let (anchors, bursts) = run.anchors();
568	        let mut barriers = run.barriers();
569	        let plan = loop {
570	            let cursor = |t: Ticks| run.cursor(t);
571	            let plan = visits::plan(anchors.clone(), &bursts, &barriers, timing, frame, &cursor);
572	            let more = run.closing_cuts(&plan.holds, &barriers);
573	            if more.is_empty() {
574	                break plan;
575	            }
576	            barriers.extend(more);
577	            barriers.sort_by_key(|b| b.at);
578	        };
579	        visit_count += plan.visits;
580	        closed += plan.closed;
581	        let moved: Vec<(u32, Planned)> = plan.actions.iter().filter_map(|p| run.land(*p)).collect();
582	        let mut run_bases: Vec<(u32, Placement)> = Vec::new();
583	        // CU-74: a hold across a cut into a given clip sets its base.
584	        for w in run.clips.windows(2) {
585	            if !run.is_given(w[1]) {
586	                continue;
587	            }
588	            let cut = end(w[0]);
589	            let in_force = moved
590	                .iter()
591	                .filter(|(_, p)| p.to <= cut)
592	                .max_by_key(|(_, p)| p.to)
593	                .and_then(|(_, p)| p.aim);
594	            if let Some(aim) = in_force {
595	                let target = next.require_clip(w[1].id)?;
596	                let region = zoom_region(&next, target, 0, aim, scale);
597	                let set = next.zoom_placement(target, 0, &region, ZoomFit::Fit);
598	                run_bases.push((w[1].id, set));
599	            }
600	        }
601	        // CU-71: Replace resets a later clip moved by no kept action.
602	        if args.replace {
603	            for c in run.clips.iter().skip(1).filter(|c| run.is_given(c)) {
604	                let kept = next.require_clip(c.id)?;
605	                let off = !same(placement(kept), rest);
606	                let set = run_bases.iter().any(|(id, _)| *id == c.id);
607	                if off && !set && !kept.actions.iter().any(moves) {
608	                    run_bases.push((c.id, rest));
609	                }
610	            }
611	        }
612	        landed.extend(moved.into_iter().map(|(id, p)| (id, p, rest, scale)));
613	        bases.extend(run_bases);
614	    }
615	    for &(id, set) in &bases {
616	        if let Some(v) = next.clip_mut(id).and_then(|c| c.video.as_mut()) {
617	            (v.scale, v.x, v.y) = set;
618	        }
619	    }
620	    landed.sort_by_key(|(_, p, _, _)| p.from);
621	    let mut ops: Vec<Value> = removed
622	        .iter()
623	        .map(|(c, a)| json!({"op": "remove_action", "clip": c, "action": a}))
624	        .collect();
625	    for (id, (scale, x, y)) in &bases {
626	        ops.push(json!({"op": "set_video", "clips": [id],
627	                        "patch": {"scale": scale, "x": x, "y": y}}));
628	    }
629	    let (mut added, mut dropped) = (0, 0);
630	    let mut actions: Vec<Value> = Vec::new();
631	    let mut busy: Vec<(u32, Ticks)> = Vec::new();
632	    for (id, p, rest, scale) in landed {
633	        let clip = next.require_clip(id)?;
634	        let mut at = next.snapped(p.from - clip.start).max(0);
635	        let mut duration = next.snapped(p.to - p.from);
636	        if let Some((_, until)) = busy.iter().find(|(c, _)| *c == id) {
637	            if at < *until {
638	                duration -= until - at;
639	                at = *until;
640	            }
641	        }
642	        duration = duration.min(clip.duration - at);
643	        if duration < next.frame() {
644	            continue;
645	        }
646	        if overlapping_action(&clip.actions, None, at, duration).is_some() {
647	            dropped += 1;
648	            continue;
649	        }
650	        busy.retain(|(c, _)| *c != id);
651	        busy.push((id, at + duration));
652	        let region = match p.aim {
653	            Some(aim) => json!(zoom_region(&next, clip, at, aim, scale)),
654	            None if same(placement(clip), rest) => Value::Null,
655	            None => json!(next.region_for_placement(clip, at, rest)),
656	        };
657	        ops.push(
658	            json!({"op": "add_zoom_action", "clip": id, "at": at, "duration": duration,
659	                        "region": region, "fit": "fit", "curve": "ease_in_out"}),
660	        );
661	        actions.push(json!({"clip": id, "at": at, "duration": duration, "kind": p.kind.name()}));
662	        added += 1;
663	    }
664	    Ok(json!({
665	        "ops": ops, "visits": visit_count, "added": added, "replaced": removed.len(),
666	        "dropped": dropped, "closed_at_cut": closed, "bases_set": bases.len(),
667	        "actions": actions,
668	    }))
669	}
