671	/// The region in Q for `aim` (in P) on `clip` at clip time `at` of the
672	/// project as it will be at apply: `region_size` at the zoomed scale and the
673	/// evaluated rotation, centred on the aim less the evaluated crop's centre.
674	fn zoom_region(next: &Project, clip: &Clip, at: Ticks, aim: (f64, f64), scale: f64) -> ZoomRegion {
675	    let v = next.evaluate_clip(clip, at).video;
676	    let canvas = (f64::from(next.canvas.width), f64::from(next.canvas.height));
677	    let (width, height) = region_size(canvas, scale, v.rotation);
678	    ZoomRegion {
679	        x: aim.0 - (v.crop.l - v.crop.r) / 2.0,
680	        y: aim.1 - (v.crop.t - v.crop.b) / 2.0,
681	        width,
682	        height,
683	    }
684	}
685	//! A run of Auto Zoom (spec §11 CU-74), cut out of `cursor_zoom.rs` by
686	//! the 400-line rule for a new file: which clips are one run, and what a run
687	//! is planned against — its given clips' anchors and scroll bursts in
688	//! container time (CU-70, CU-72), its barriers, the raw cursor for follow,
689	//! and where a planned span lands (no straddled cut, only given clips).
