700	pub(crate) fn base(clip: &Clip) -> VideoProps {
701	    clip.video.clone().unwrap_or_default()
702	}
703	
704	pub(crate) fn end(c: &Clip) -> Ticks {
705	    c.start.saturating_add(c.duration)
706	}
707	
708	pub(crate) fn media_in(clip: &Clip) -> Option<(u32, Ticks)> {
709	    match &clip.source {
710	        Source::Media {
711	            media,
712	            r#in,
713	            reversed: false,
714	        } => Some((*media, *r#in)),
715	        _ => None,
716	    }
717	}
