719	/// Whether `b` continues `a` in one run.
720	pub(crate) fn continues(a: &Clip, b: &Clip) -> bool {
721	    let (Some((ma, _)), Some((mb, ib))) = (media_in(a), media_in(b)) else {
722	        return false;
723	    };
724	    let advanced = match source_advanced_through(a, a.duration) {
725	        Source::Media { r#in, .. } => r#in,
726	        _ => return false,
727	    };
728	    ma == mb && b.start == end(a) && ib == advanced
729	}
