731	/// The run `clip` is in, in time order.
732	pub(crate) fn run_of<'p>(project: &'p Project, clip: &Clip) -> Vec<&'p Clip> {
733	    let mut on: Vec<&Clip> = project
734	        .clips
735	        .iter()
736	        .filter(|c| c.track == clip.track)
737	        .collect();
738	    on.sort_by_key(|c| c.start);
739	    let Some(at) = on.iter().position(|c| c.id == clip.id) else {
740	        return Vec::new();
741	    };
742	    let (mut lo, mut hi) = (at, at);
743	    while lo > 0 && continues(on[lo - 1], on[lo]) {
744	        lo -= 1;
745	    }
746	    while hi + 1 < on.len() && continues(on[hi], on[hi + 1]) {
747	        hi += 1;
748	    }
749	    on[lo..=hi].to_vec()
750	}
