752	/// Clip time for `read` source ticks past `in`: through S on a ramp,
753	/// `⌊read / speed⌋` otherwise.
754	pub(crate) fn clip_time(clip: &Clip, read: Ticks) -> Ticks {
755	    if is_ramped(clip) {
756	        return time_for_source(clip, read).unwrap_or(0);
757	    }
758	    (read as f64 / clip.speed).floor() as Ticks
759	}
