761	/// What a run is planned against.
762	pub(crate) struct Run<'a> {
763	    pub clips: Vec<&'a Clip>,
764	    pub given: &'a [u32],
765	    pub tracks: &'a [&'a CursorTrack],
766	    /// The project as it will be at apply (Replace's removals made).
767	    pub next: &'a Project,
768	    pub window: (Ticks, Ticks),
769	    pub typing: bool,
770	    /// Half the media's size, P's origin in movie px.
771	    pub half: (f64, f64),
772	}
773	
774	impl Run<'_> {
775	    pub(crate) fn is_given(&self, c: &Clip) -> bool {
776	        self.given.contains(&c.id)
777	    }
778	
779	    fn track(&self, c: &Clip) -> Option<&CursorTrack> {
780	        let i = self.given.iter().position(|&g| g == c.id)?;
781	        self.tracks.get(i).copied()
782	    }
783	
784	    fn p(&self, track: &CursorTrack, t_us: f64, x: i64, y: i64) -> (f64, f64) {
785	        let (mx, my) = track.to_movie(t_us, x as f64, y as f64);
786	        (mx - self.half.0, my - self.half.1)
787	    }
788	
789	    /// The region's size at `scale` and the cropped rect, from the run's
790	    /// first given clip.
791	    pub(crate) fn frame(&self, scale: f64) -> Frame {
792	        let first = self.clips.iter().find(|c| self.is_given(c));
793	        let v = first.map(|c| base(c)).unwrap_or_default();
794	        let canvas = (
795	            f64::from(self.next.canvas.width),
796	            f64::from(self.next.canvas.height),
797	        );
798	        let (hw, hh) = self.half;
799	        Frame {
800	            size: region_size(canvas, scale, v.rotation),
801	            min: (-hw + v.crop.l, -hh + v.crop.t),
802	            max: (hw - v.crop.r, hh - v.crop.b),
803	        }
804	    }
805	
806	    /// Every given clip's anchors (CU-70, CU-72) and scroll-burst starts,
807	    /// in container time.
808	    pub(crate) fn anchors(&self) -> (Vec<Anchor>, Vec<Ticks>) {
809	        let (mut anchors, mut bursts) = (Vec::new(), Vec::new());
810	        for &c in self.clips.iter().filter(|c| self.is_given(c)) {
811	            let (Some(track), Some((_, source_in))) = (self.track(c), media_in(c)) else {
812	                continue;
813	            };
814	            let length = self.next.content_length_in_source(c);
815	            let file = track.file();
816	            let inside = |us: i64| {
817	                let s = us_to_ticks(us);
818	                (source_in <= s && s < source_in.saturating_add(length))
819	                    .then(|| c.start.saturating_add(clip_time(c, s - source_in)))
820	            };
821	            let kept = |t: Ticks| self.window.0 <= t && t < self.window.1;
822	            let k = &file.clicks;
823	            let downs: Vec<usize> = (0..k.t.len()).filter(|&i| k.down[i] == 1).collect();
824	            for &i in &downs {
825	                if let Some(t) = inside(k.t[i]).filter(|&t| kept(t)) {
826	                    let p = self.p(track, k.t[i] as f64, k.x[i], k.y[i]);
827	                    anchors.push(Anchor { t, end: t, p });
828	                }
829	            }
830	            if self.typing {
831	                for (first, last, _) in typing_stretches(&file.keys.typed.t) {
832	                    let Some(t) = inside(first).filter(|&t| kept(t)) else {
833	                        continue;
834	                    };
835	                    let read = us_to_ticks(last) - source_in;
836	                    let until = c.start.saturating_add(clip_time(c, read)).max(t);
837	                    // CU-72: the last down click at or before the first mark.
838	                    let aim = downs.iter().rev().find(|&&i| k.t[i] <= first);
839	                    let p = match aim {
840	                        Some(&i) => self.p(track, k.t[i] as f64, k.x[i], k.y[i]),
841	                        None => match track.raw_at(first as f64) {
842	                            Some((x, y)) => {
843	                                let (mx, my) = track.to_movie(first as f64, x, y);
844	                                (mx - self.half.0, my - self.half.1)
845	                            }
846	                            None => continue,
847	                        },
848	                    };
849	                    anchors.push(Anchor { t, end: until, p });
850	                }
851	            }
852	            for (first, _, _) in scroll_bursts(&file.scrolls.t) {
853	                bursts.extend(inside(first));
854	            }
855	        }
856	        bursts.sort_unstable();
857	        (anchors, bursts)
858	    }
859	
860	    /// Cuts into a clip that was not given, and the run's end.
861	    pub(crate) fn barriers(&self) -> Vec<Barrier> {
862	        let mut out: Vec<Barrier> = self
863	            .clips
864	            .windows(2)
865	            .filter(|w| !self.is_given(w[1]))
866	            .map(|w| Barrier {
867	                at: end(w[0]),
868	                counted: true,
869	            })
870	            .collect();
871	        if let Some(last) = self.clips.last() {
872	            out.push(Barrier {
873	                at: end(last),
874	                counted: false,
875	            });
876	        }
877	        out
878	    }
879	
880	    /// Cuts a hold crosses into a given clip with a kept action meeting
881	    /// the hold, not yet barriers.
882	    pub(crate) fn closing_cuts(&self, holds: &[(Ticks, Ticks)], have: &[Barrier]) -> Vec<Barrier> {
883	        let mut out: Vec<Barrier> = Vec::new();
884	        for w in self.clips.windows(2) {
885	            let cut = end(w[0]);
886	            if have.iter().chain(&out).any(|b| b.at == cut) {
887	                continue;
888	            }
889	            let Some(after) = self.next.clip(w[1].id) else {
890	                continue;
891	            };
892	            let hit = holds.iter().any(|&(lo, hi)| {
893	                lo < cut
894	                    && cut < hi
895	                    && after.actions.iter().any(|a| {
896	                        let s = after.start.saturating_add(a.start);
897	                        s < hi && cut < s.saturating_add(a.duration)
898	                    })
899	            });
900	            if hit {
901	                out.push(Barrier {
902	                    at: cut,
903	                    counted: true,
904	                });
905	            }
906	        }
907	        out
908	    }
909	
910	    /// The raw cursor in P at container time `t`, inside a given clip.
911	    pub(crate) fn cursor(&self, t: Ticks) -> Option<(f64, f64)> {
912	        let c = self
913	            .clips
914	            .iter()
915	            .find(|c| self.is_given(c) && c.start <= t && t < end(c))?;
916	        let track = self.track(c)?;
917	        let (_, source_in) = media_in(c)?;
918	        let us = ticks_to_us(source_in.saturating_add(source_read_by(c, t - c.start)));
919	        let (x, y) = track.raw_at(us)?;
920	        let (mx, my) = track.to_movie(us, x, y);
921	        Some((mx - self.half.0, my - self.half.1))
922	    }
923	
924	    /// CU-74: the given clip a planned span lands on, the span moved so it
925	    /// straddles no cut and held inside the clip.
926	    pub(crate) fn land(&self, mut p: Planned) -> Option<(u32, Planned)> {
927	        let mid = p.from + (p.to - p.from) / 2;
928	        let overlap = |c: &Clip| (p.to.min(end(c)) - p.from.max(c.start)).max(0);
929	        let distance = |c: &Clip| (c.start - p.to).max(p.from - end(c)).max(0);
930	        let target = self
931	            .clips
932	            .iter()
933	            .find(|c| self.is_given(c) && c.start <= mid && mid < end(c))
934	            .or_else(|| {
935	                self.clips
936	                    .iter()
937	                    .filter(|c| self.is_given(c))
938	                    .min_by_key(|c| (-overlap(c), distance(c)))
939	            })?;
940	        let d = p.to - p.from;
941	        if p.from < target.start {
942	            (p.from, p.to) = (target.start, target.start + d);
943	        }
944	        if p.to > end(target) {
945	            (p.from, p.to) = (end(target) - d, end(target));
946	        }
947	        p.from = p.from.max(target.start);
948	        Some((target.id, p))
949	    }
950	}
