47	/// The region's size and the cropped rect it is clamped inside, in P.
48	#[derive(Debug, Clone, Copy)]
49	pub(crate) struct Frame {
50	    pub size: (f64, f64),
51	    pub min: (f64, f64),
52	    pub max: (f64, f64),
53	}
54	
55	impl Frame {
56	    /// The region centre for an aim: clamped so the region stays inside
57	    /// the cropped rect, centred on an axis it exceeds.
58	    pub(crate) fn clamp(&self, p: (f64, f64)) -> (f64, f64) {
59	        let axis = |v: f64, size: f64, lo: f64, hi: f64| {
60	            if size >= hi - lo {
61	                (lo + hi) / 2.0
62	            } else {
63	                v.clamp(lo + size / 2.0, hi - size / 2.0)
64	            }
65	        };
66	        (
67	            axis(p.0, self.size.0, self.min.0, self.max.0),
68	            axis(p.1, self.size.1, self.min.1, self.max.1),
69	        )
70	    }
71	
72	    fn outside(&self, centre: (f64, f64), p: (f64, f64), half: f64) -> bool {
73	        (p.0 - centre.0).abs() > half * self.size.0 || (p.1 - centre.1).abs() > half * self.size.1
74	    }
75	}
