134	struct Visit {
135	    anchors: Vec<Anchor>,
136	    last: Ticks,
137	    back: Ticks,
138	}
139	
140	/// Anchors (any order), scroll-burst starts, barriers, the figures and the
141	/// frame, and the cursor in P at a container time → the run's plan.
142	pub(crate) fn plan(
143	    mut anchors: Vec<Anchor>,
144	    bursts: &[Ticks],
145	    barriers: &[Barrier],
146	    timing: Timing,
147	    frame: Frame,
148	    cursor: &dyn Fn(Ticks) -> Option<(f64, f64)>,
149	) -> Plan {
150	    anchors.sort_by_key(|a| a.t);
151	    let barrier_in = |lo: Ticks, hi: Ticks| barriers.iter().any(|b| lo < b.at && b.at <= hi);
152	    let mut visits: Vec<Visit> = Vec::new();
153	    for a in anchors {
154	        let joins = visits.last().is_some_and(|v| {
155	            let prev = v.anchors.last().map_or(a.t, |p| p.t);
156	            a.t <= v.last + timing.stay
157	                && !bursts.iter().any(|&b| v.last < b && b < a.t)
158	                && !barrier_in(prev, a.t)
159	        });
160	        match visits.last_mut() {
161	            Some(v) if joins => {
162	                v.last = v.last.max(a.end);
163	                v.anchors.push(a);
164	            }
165	            _ => visits.push(Visit {
166	                anchors: vec![a],
167	                last: a.end,
168	                back: 0,
169	            }),
170	        }
171	    }
172	    let mut out = Plan {
173	        visits: visits.len(),
174	        ..Plan::default()
175	    };
176	    // Each visit's zoom back: Stay after its last activity, or the first
177	    // scroll burst after its last anchor, closed at the next barrier.
178	    let mut closed_by = vec![false; visits.len()];
179	    for (i, v) in visits.iter_mut().enumerate() {
180	        let last_anchor = v.anchors.last().map_or(0, |a| a.t);
181	        let mut back = v.last + timing.stay;
182	        if let Some(&b) = bursts.iter().find(|&&b| b > last_anchor) {
183	            back = back.min(b);
184	        }
185	        if let Some(bar) = barriers.iter().find(|b| b.at > last_anchor) {
186	            if back + BACK > bar.at {
187	                back = bar.at - BACK;
188	                closed_by[i] = true;
189	                if bar.counted {
190	                    out.closed += 1;
191	                }
192	            }
193	        }
194	        v.back = back;
195	    }
196	    // Chains: a visit whose zoom back would end under MERGE_GAP before the
197	    // next one's zoom-in starts runs on into it with one pan.
198	    let mut chains: Vec<Vec<usize>> = Vec::new();
199	    for i in 0..visits.len() {
200	        let merge = i > 0 && !closed_by[i - 1] && {
201	            let (v, w) = (&visits[i - 1], &visits[i]);
202	            let next = w.anchors[0].t;
203	            let prev = v.anchors.last().map_or(next, |a| a.t);
204	            next - timing.lead - (v.back + BACK) < MERGE_GAP && !barrier_in(prev, next)
205	        };
206	        match chains.last_mut() {
207	            Some(chain) if merge => chain.push(i),
208	            _ => chains.push(vec![i]),
209	        }
210	    }
211	    for chain in chains {
212	        plan_chain(&chain, &visits, timing, frame, cursor, &mut out);
213	    }
214	    out
215	}
216	
217	/// One hold: a zoom-in, the anchors' pans (a merged visit's first anchor
218	/// always pans), follow pans, a zoom back.
219	fn plan_chain(
220	    chain: &[usize],
221	    visits: &[Visit],
222	    timing: Timing,
223	    frame: Frame,
224	    cursor: &dyn Fn(Ticks) -> Option<(f64, f64)>,
225	    out: &mut Plan,
226	) {
227	    let mut anchors: Vec<(Anchor, bool)> = Vec::new();
228	    for (k, &i) in chain.iter().enumerate() {
229	        for (j, a) in visits[i].anchors.iter().enumerate() {
230	            anchors.push((*a, k > 0 && j == 0));
231	        }
232	    }
233	    let back = visits[chain[chain.len() - 1]].back;
234	    let first = anchors[0].0;
235	    let mut region = frame.clamp(first.p);
236	    let hold_start = first.t - timing.lead;
237	    out.actions.push(Planned {
238	        from: hold_start,
239	        to: first.t,
240	        kind: Kind::In,
241	        aim: Some(region),
242	    });
243	    let mut busy = first.t;
244	    let mut next = 1;
245	    let mut t = first.t;
246	    let mut outside_since: Option<Ticks> = None;
247	    let mut last_follow: Option<Ticks> = None;
248	    loop {
249	        while next < anchors.len() && anchors[next].0.t - timing.lead <= t {
250	            let (a, forced) = anchors[next];
251	            if forced || frame.outside(region, a.p, ANCHOR_HALF) {
252	                let start = (a.t - timing.lead).max(busy);
253	                if a.t - start >= timing.frame {
254	                    region = frame.clamp(a.p);
255	                    out.actions.push(Planned {
256	                        from: start,
257	                        to: a.t,
258	                        kind: Kind::Pan,
259	                        aim: Some(region),
260	                    });
261	                    busy = a.t;
262	                }
263	            }
264	            outside_since = None;
265	            next += 1;
266	        }
267	        if t >= back {
268	            break;
269	        }
270	        let watched = timing.follow && t >= busy;
271	        match watched.then(|| cursor(t)).flatten() {
272	            Some(p) if frame.outside(region, p, FOLLOW_HALF) => {
273	                let since = *outside_since.get_or_insert(t);
274	                let end = t + FOLLOW_PAN;
275	                let free = !anchors[next..]
276	                    .iter()
277	                    .any(|(a, _)| a.t - timing.lead < end && t < a.t);
278	                if t - since >= FOLLOW_OUTSIDE
279	                    && last_follow.is_none_or(|l| t - l >= FOLLOW_EVERY)
280	                    && end <= back
281	                    && free
282	                {
283	                    region = frame.clamp(p);
284	                    out.actions.push(Planned {
285	                        from: t,
286	                        to: end,
287	                        kind: Kind::Follow,
288	                        aim: Some(region),
289	                    });
290	                    busy = end;
291	                    last_follow = Some(t);
292	                    outside_since = None;
293	                }
294	            }
295	            _ => outside_since = None,
296	        }
297	        t += SAMPLE;
298	    }
299	    let from = back.max(busy);
300	    let to = back + BACK;
301	    if to - from >= timing.frame {
302	        out.actions.push(Planned {
303	            from,
304	            to,
305	            kind: Kind::Back,
306	            aim: None,
307	        });
308	    }
309	    out.holds.push((hold_start, to));
310	}
311	//! Bursts of input in a cursor file (spec §11 CU-25, CU-70): the typing
312	//! stretches an `events` request answers and Auto Zoom anchors on, and the
313	//! scroll bursts that end an Auto Zoom visit, by CU7's figures. CU9b reads
314	//! the same stretches. Both are one run finder with their own figures.
315	
316	/// Marks closer than this belong to one stretch (strictly under 1.0 s).
317	pub const TYPING_GAP_US: i64 = 1_000_000;
318	/// The fewest marks a stretch holds.
319	pub const TYPING_MIN_MARKS: usize = 3;
320	/// Wheel events closer than this belong to one burst (strictly under 1.0 s).
321	pub const SCROLL_GAP_US: i64 = 1_000_000;
322	/// The fewest wheel events a burst holds.
323	pub const SCROLL_MIN_EVENTS: usize = 3;
324	
325	/// Each run of `t` (µs, in order) whose neighbours are less than `gap`
326	/// apart and which holds at least `min` entries, as (first, last, count).
327	fn runs(t: &[i64], gap: i64, min: usize) -> Vec<(i64, i64, usize)> {
328	    let mut out = Vec::new();
329	    let mut start = 0;
330	    for i in 1..=t.len() {
331	        if i == t.len() || t[i] - t[i - 1] >= gap {
332	            if i - start >= min {
333	                out.push((t[start], t[i - 1], i - start));
334	            }
335	            start = i;
336	        }
337	    }
338	    out
339	}
340	
341	/// The typing stretches of `t` (the `typed` marks' µs, in order): each run
342	/// of marks less than `TYPING_GAP_US` apart holding at least
343	/// `TYPING_MIN_MARKS`, as (first mark, last mark, marks).
344	pub(crate) fn typing_stretches(t: &[i64]) -> Vec<(i64, i64, usize)> {
345	    runs(t, TYPING_GAP_US, TYPING_MIN_MARKS)
346	}
347	
348	/// The scroll bursts of `t` (the `scrolls`' µs, in order): each run of
349	/// wheel events less than `SCROLL_GAP_US` apart holding at least
350	/// `SCROLL_MIN_EVENTS`, as (first, last, events).
351	pub(crate) fn scroll_bursts(t: &[i64]) -> Vec<(i64, i64, usize)> {
352	    runs(t, SCROLL_GAP_US, SCROLL_MIN_EVENTS)
353	}
354	//! `plan_zooms`, Auto Zoom's planner (spec §11 CU-70…CU-75): the selected
355	//! clips' cursor files read into anchors, planned as visits by
356	//! `cursor_zoom_visits.rs`, moved onto clips and answered as ops — every
357	//! `remove_action` (Replace), then every `set_video`, then every
358	//! `add_zoom_action` in time order — that the app applies as ONE undo step.
359	//! Nothing here edits; the plan is checked against the project as it will
360	//! be at apply, so no op refuses there.
361	//!
362	//! **Runs (CU-74).** Clips on one track, each touching the one before, of
363	//! one media, forward, each continuing the other's source — the halves of a
364	//! split — are one run, formed over the whole track. The rest placement is
365	//! the run's first clip's base `scale`, `x`, `y`, and every zoom back ends
366	//! there. Planned actions land only on given clips and never straddle a
367	//! cut; a hold across a cut into a given clip sets its base to the
368	//! placement in force, or, when that clip was not given or has a kept
369	//! action meeting the hold, the cut is a barrier the visit closes at.
370	
371	use serde::Deserialize;
372	use serde_json::{json, Value};
