383	/// A rest placement equal to a base, each number to this.
384	const SAME: f64 = 1e-9;
385	/// A run's rest scale may sit this far under the fit before it is placed.
386	const PLACED_TOLERANCE: f64 = 0.001;
387	
388	/// A base's `scale`, `x`, `y`.
389	type Placement = (f64, f64, f64);
390	
391	fn default_zoom() -> f64 {
392	    2.0
393	}
394	fn default_lead() -> f64 {
395	    0.6
396	}
397	fn default_stay() -> f64 {
398	    2.5
399	}
400	fn yes() -> bool {
401	    true
402	}
