404	/// `plan_zooms`' request (CU-70's defaults); `lead` and `stay` in seconds,
405	/// `from` and `to` container ticks.
406	#[derive(Deserialize)]
407	#[serde(deny_unknown_fields)]
408	pub(crate) struct PlanZoomsArgs {
409	    #[serde(default)]
410	    pub clips: Vec<u32>,
411	    #[serde(default = "default_zoom")]
412	    pub zoom: f64,
413	    #[serde(default = "default_lead")]
414	    pub lead: f64,
415	    #[serde(default = "default_stay")]
416	    pub stay: f64,
417	    #[serde(default = "yes")]
418	    pub follow: bool,
419	    #[serde(default = "yes")]
420	    pub typing: bool,
421	    #[serde(default)]
422	    pub replace: bool,
423	    #[serde(default)]
424	    pub from: Option<Ticks>,
425	    #[serde(default)]
426	    pub to: Option<Ticks>,
427	}
