429	fn in_range(name: &str, unit: &str, v: f64, lo: f64, hi: f64) -> Result<(), String> {
430	    if v.is_finite() && (lo..=hi).contains(&v) {
431	        return Ok(());
432	    }
433	    Err(format!("{name} is {v}{unit}; it runs {lo}–{hi}"))
434	}
435	
436	fn placement(clip: &Clip) -> Placement {
437	    let v = base(clip);
438	    (v.scale, v.x, v.y)
439	}
440	
441	fn same(a: Placement, b: Placement) -> bool {
442	    (a.0 - b.0).abs() <= SAME && (a.1 - b.1).abs() <= SAME && (a.2 - b.2).abs() <= SAME
443	}
444	
445	/// Checks every clip in CU-75's order; answers each clip's run.
446	fn check<'p>(project: &'p Project, clips: &[u32]) -> Result<Vec<Vec<&'p Clip>>, String> {
447	    let mut runs = Vec::new();
448	    for (i, &id) in clips.iter().enumerate() {
449	        if clips[..i].contains(&id) {
450	            return Err(format!("clip {id} is named twice"));
451	        }
452	        let clip = project.require_clip(id)?;
453	        let Source::Media {
454	            media, reversed, ..
455	        } = &clip.source
456	        else {
457	            return Err(format!("clip {id} is not a media clip"));
458	        };
459	        let found = project.media(*media);
460	        if found.and_then(|m| m.cursor.as_ref()).is_none() {
461	            return Err(format!("clip {id}'s media {media} has no cursor file"));
462	        }
463	        if *reversed {
464	            return Err(format!(
465	                "clip {id} plays reversed; Auto Zoom plans only clips that play forward"
466	            ));
467	        }
468	        let picture = clip.video.is_some() && found.is_some_and(|m| m.has_video);
469	        let Some((sw, sh)) = project.source_size(clip).filter(|_| picture) else {
470	            return Err(format!("clip {id} has no picture"));
471	        };
472	        let run = run_of(project, clip);
473	        let rest = run.first().map_or(1.0, |c| base(c).scale);
474	        if rest < project.fit_scale(sw, sh) * (1.0 - PLACED_TOLERANCE) {
475	            return Err(format!(
476	                "clip {id} is placed smaller than the canvas; a zoom would fill the canvas. \
477	                 Nest it (Clip ▸ Nest) and run Auto Zoom inside the nest."
478	            ));
479	        }
480	        runs.push(run);
481	    }
482	    Ok(runs)
483	}
