924	    /// CU-74: the given clip a planned span lands on, the span moved so it
925	    /// straddles no cut and held inside the clip.
926	    pub(crate) fn land(&self, mut p: Planned) -> Option<(u32, Planned)> {
927	        let mid = p.from + (p.to - p.from) / 2;
928	        let overlap = |c: &Clip| (p.to.min(end(c)) - p.from.max(c.start)).max(0);
929	        let distance = |c: &Clip| (c.start - p.to).max(p.from - end(c)).max(0);
930	        let target = self
931	            .clips
932	            .iter()
933	            .find(|c| self.is_given(c) && c.start <= mid && mid < end(c))
934	            .or_else(|| {
935	                self.clips
936	                    .iter()
937	                    .filter(|c| self.is_given(c))
938	                    .min_by_key(|c| (-overlap(c), distance(c)))
939	            })?;
940	        let d = p.to - p.from;
941	        if p.from < target.start {
942	            (p.from, p.to) = (target.start, target.start + d);
943	        }
944	        if p.to > end(target) {
945	            (p.from, p.to) = (end(target) - d, end(target));
946	        }
947	        p.from = p.from.max(target.start);
948	        Some((target.id, p))
949	    }
